Task: Write a Swift function that returns the first index of the largest value, or nil for an empty array.
Solution:
func firstMaximumIndex(_ values: [Int]) -> Int? {
  guard var best = values.first else { return nil }
  var bestIndex = 0
  for index in values.indices.dropFirst() where values[index] > best {
    best = values[index]
    bestIndex = index
  }
  return bestIndex
}
